const AIGatewayModelListResponseSchema = z
  .object({
    models: z
      .array(
        z
          .object({
            cache_read_usd_per_million_tokens: z
              .number()
              .openapi({ description: 'USD per million tokens read from the cache' }),
            cache_write_usd_per_million_tokens: z
              .number()
              .openapi({ description: 'USD per million tokens written to the cache' }),
            context_window_tokens: z
              .int()
              .min(0)
              .openapi({ description: 'Size of the context window' }),
            creator: z.string().openapi({ description: 'Company behind the model' }),
            featured: z
              .boolean()
              .openapi({ description: 'Whether the model is shown ahead of the rest' }),
            input_usd_per_million_tokens: z
              .number()
              .openapi({ description: 'USD per million input tokens' }),
            model_name: z.string().openapi({ description: 'Name of the model' }),
            output_usd_per_million_tokens: z
              .number()
              .openapi({ description: 'USD per million output tokens' }),
            provider: z.string().openapi({ description: 'Same as creator' }),
          })
          .openapi({
            required: [
              'cache_read_usd_per_million_tokens',
              'cache_write_usd_per_million_tokens',
              'context_window_tokens',
              'creator',
              'featured',
              'input_usd_per_million_tokens',
              'model_name',
              'output_usd_per_million_tokens',
              'provider',
            ],
          }),
      )
      .openapi({ description: 'List of AI Gateway models' }),
  })
  .openapi({ description: 'AIGatewayModelListResponse', required: ['models'] })
  .openapi('AIGatewayModelListResponse')

const AIGatewayUsageGetResponseSchema = z
  .object({
    usage: z
      .array(
        z
          .object({
            cache_read_tokens: z
              .int()
              .min(0)
              .openapi({ description: 'Share of the input tokens served from the prompt cache' }),
            cache_write_tokens: z
              .int()
              .min(0)
              .openapi({ description: 'Share of the input tokens written to the prompt cache' }),
            estimated_cost_usd: z
              .number()
              .exactOptional()
              .openapi({
                description:
                  'Estimate at the rates the catalogue lists now, or null for a model it no longer lists',
              }),
            input_tokens: z
              .int()
              .min(0)
              .openapi({ description: 'Tokens sent to the model, prompt cache included' }),
            key_id: z
              .string()
              .length(36)
              .exactOptional()
              .openapi({
                description:
                  'Key the usage is attributed to, or null for the whole project in that time bucket',
              }),
            model_name: z.string().openapi({ description: 'Name of the model' }),
            output_tokens: z.int().min(0).openapi({ description: 'Tokens returned by the model' }),
            request_count: z
              .int()
              .min(0)
              .openapi({ description: 'Number of requests made to the model' }),
            timestamp: z
              .string()
              .max(36)
              .openapi({
                description:
                  'Start of the UTC minute, hour or day the usage falls in, per the granularity asked for',
              }),
            total_tokens: z.int().min(0).openapi({ description: 'Tokens sent and returned' }),
            uncached_input_tokens: z
              .int()
              .min(0)
              .openapi({ description: 'Share of the input tokens that missed the prompt cache' }),
          })
          .openapi({
            required: [
              'cache_read_tokens',
              'cache_write_tokens',
              'input_tokens',
              'model_name',
              'output_tokens',
              'request_count',
              'timestamp',
              'total_tokens',
              'uncached_input_tokens',
            ],
          }),
      )
      .openapi({ description: 'AI Gateway usage per key, time bucket and model' }),
  })
  .openapi({ description: 'AIGatewayUsageGetResponse', required: ['usage'] })
  .openapi('AIGatewayUsageGetResponse')

const AccountAttachPaymentMethodResponseSchema = z
  .object({
    card: z
      .object({
        brand: z.string().openapi({ description: 'Brand' }),
        card_id: z.string().max(64).openapi({ description: 'Credit card ID' }),
        country: z.string().max(128).openapi({ description: 'Country' }),
        country_code: z.string().max(2).openapi({ description: 'Two letter ISO country code' }),
        exp_month: z.int().min(1).max(12).openapi({ description: 'Expiration month' }),
        exp_year: z.int().min(2015).max(2100).openapi({ description: 'Expiration year' }),
        last4: z.string().openapi({ description: 'Credit card last four digits' }),
        name: z.string().max(256).openapi({ description: 'Name on the credit card' }),
        organization_id: z
          .string()
          .max(36)
          .exactOptional()
          .openapi({ description: 'Organization ID' }),
        projects: z
          .array(z.string())
          .openapi({ description: 'List of projects the card is assigned to' }),
      })
      .openapi({
        description: 'User credit card information',
        required: [
          'brand',
          'card_id',
          'country',
          'country_code',
          'exp_month',
          'exp_year',
          'last4',
          'name',
          'projects',
        ],
      }),
    errors: z
      .array(
        z
          .object({
            message: z.string().openapi({ description: 'Printable error message' }),
            more_info: z
              .string()
              .exactOptional()
              .openapi({ description: 'URL to the documentation of the error' }),
            status: z.int().openapi({ description: 'HTTP error status code' }),
          })
          .openapi({ required: ['message', 'status'] }),
      )
      .exactOptional()
      .openapi({ description: 'List of errors occurred during request processing' }),
    message: z.string().exactOptional().openapi({ description: 'Printable result of the request' }),
  })
  .openapi({ description: 'AccountAttachPaymentMethodResponse', required: ['card'] })
  .openapi('AccountAttachPaymentMethodResponse')

const AccountAuthenticationMethodCreateRequestBodySchema = z
  .object({
    auth_token_extend_when_used: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({ description: 'Extend authentication token validity when used' }),
    auth_token_max_age_seconds: z
      .int()
      .min(300)
      .max(1296000)
      .default(36000)
      .exactOptional()
      .openapi({ description: 'Auth Token Max Age Seconds' }),
    authentication_method_name: z
      .string()
      .max(128)
      .openapi({ description: 'Authentication Method Name' }),
    authentication_method_type: z
      .enum(['internal', 'saml'])
      .openapi({ description: 'An enumeration.', title: 'Authentication method type' }),
    auto_join_team_id: z
      .string()
      .max(32)
      .exactOptional()
      .openapi({
        description:
          'Deprecated; always null. Teams are being sunset, so this value is ignored on writes and always returned as null.',
      }),
    auto_join_user_group_id: z
      .string()
      .max(36)
      .exactOptional()
      .openapi({
        description:
          'Automatically add users to a group, when user signs up using this authentication method',
      }),
    linked_domains: z
      .array(
        z
          .object({ domain_id: z.string().max(36).openapi({ description: 'Domain ID' }) })
          .openapi({ required: ['domain_id'] }),
      )
      .exactOptional()
      .openapi({ description: 'Linked Domains' }),
    saml_assertion_signed_enabled: z
      .boolean()
      .exactOptional()
      .openapi({ description: "Set to 'true' to enable WantAssertionsSigned" }),
    saml_authn_requests_signed_enabled: z
      .boolean()
      .exactOptional()
      .openapi({ description: "Set to 'true' to enable AuthnRequestsSigned" }),
    saml_certificate: z
      .string()
      .max(16384)
      .exactOptional()
      .openapi({ description: "Identity provider's certificate" }),
    saml_digest_algorithm: z
      .enum(['sha1', 'sha256', 'sha384', 'sha512'])
      .default('sha256')
      .exactOptional()
      .openapi({
        description: 'An enumeration.',
        title:
          'Digest algorithm. This is an advanced option that typically does not need to be set.',
      }),
    saml_entity_id: z.string().max(2048).exactOptional().openapi({ description: 'Saml Entity ID' }),
    saml_field_mapping: z
      .object({
        email: z
          .string()
          .max(256)
          .default('email')
          .exactOptional()
          .openapi({ description: 'Field name for user email' }),
        first_name: z
          .string()
          .max(256)
          .default('first_name')
          .exactOptional()
          .openapi({ description: "Field name for user's first name" }),
        groups: z
          .string()
          .max(256)
          .default('groups')
          .exactOptional()
          .openapi({
            description:
              "Field name for user's groups memberships. Contents of this field are used to handle group memberships when SCIM is not available and SAML is used to manage group memberships.",
          }),
        identity: z
          .string()
          .max(256)
          .default('email')
          .exactOptional()
          .openapi({
            description:
              "Field name for user's identity. This field must always exist in responses, and must be immutable and unique. Contents of this field are used to identify the user. Using user ID (such as unix user ID) is highly recommended, as email address may change, requiring relinking user to Aiven user.",
          }),
        last_name: z
          .string()
          .max(256)
          .default('last_name')
          .exactOptional()
          .openapi({ description: "Field name for user's lastname" }),
        real_name: z
          .string()
          .max(256)
          .exactOptional()
          .openapi({
            description:
              "Field name for user's full name. If specified, first_name and last_name mappings are ignored",
          }),
      })
      .exactOptional()
      .openapi({ description: 'SAMLFieldMapping', required: [] }),
    saml_idp_login_allowed: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({ description: "Set to 'true' to enable IdP initiated login" }),
    saml_idp_url: z.string().max(2048).exactOptional().openapi({ description: 'Saml Idp Url' }),
    saml_join_groups: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({ description: 'SAML join groups enabled' }),
    saml_requested_authn_context_enabled: z
      .boolean()
      .exactOptional()
      .openapi({ description: "Set to 'false' to disable RequestedAuthnContext" }),
    saml_signature_algorithm: z
      .enum(['rsa-sha1', 'dsa-sha1', 'rsa-sha256', 'rsa-sha384', 'rsa-sha512'])
      .default('rsa-sha256')
      .exactOptional()
      .openapi({ description: 'An enumeration.', title: 'SAMLSignatureAlgorithm' }),
    saml_variant: z
      .literal('adfs')
      .exactOptional()
      .openapi({ description: 'An enumeration.', title: 'SAMLVariant' }),
    scim_enabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({ description: 'SCIM enabled' }),
  })
  .openapi({
    description: 'AccountAuthenticationMethodCreateRequestBody',
    required: ['authentication_method_name', 'authentication_method_type'],
  })
  .openapi('AccountAuthenticationMethodCreateRequestBody')

