const AigatewaykeylistLimitParamsSchema = z
  .preprocess(
    (val) =>
      typeof val === 'string' &&
      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
        ? Number(val)
        : val,
    z.int().min(30).max(999),
  )
  .exactOptional()
  .openapi({
    param: {
      in: 'query',
      name: 'limit',
      description: 'Limit results to this number',
      schema: { type: 'integer', minimum: 30, maximum: 999 },
      required: false,
    },
  })

